'use client'

import * as React from 'react'

// `./button` and not `../button/button`: see the note in ./button.ts. The
// installed layout is flat, so this is the path that is correct for a consumer,
// and the shim is what makes it correct here too.
import { Button } from './button'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled TutorialStep, and `tsc --noEmit` passes on
// it, so the gate cannot catch it.
import './tutorial-step.css'
import { TickGlyph } from './glyphs'

/**
 * TutorialStep: one step of a sequence, with the way forward attached.
 *
 * "Step 2 of 5" rides `data-gs-step` and `data-gs-max`, and `data-gs-max` is
 * the same attribute progress uses because "step 2 of 5" and "2 of 5 segments
 * filled" are the same idea expressed twice. `data-gs-active` is the step the
 * sequence has got to, which is not `data-gs-selected`: the player did not pick
 * it and cannot unpick it. A finished sequence carries `data-gs-complete`.
 *
 * Like the coach mark it does not trap focus and does not move it. Its
 * controls are `button`, in document order, and Tab leaves the step at the end
 * of them.
 *
 * It performs nothing. It does not advance itself, count steps, or decide when
 * a sequence is done. `onNext` and `onBack` report the press and the host owns
 * everything behind it.
 */

export interface TutorialStepProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  /** Position in the sequence, from 1. */
  step: number
  /** The total. The same attribute progress uses, on purpose. */
  max: number
  /** The step's heading. The body is `children`. */
  title: string
  /** The one the sequence is on now. */
  active?: boolean
  /** Finished. A step the player has been through, or a sequence that is done. */
  complete?: boolean
  /**
   * Available later, not now. The step keeps its shape and its way forward
   * shows a padlock, which is what `button` already does with `locked`.
   */
  locked?: boolean
  /** Called on the way forward. Absent means this step has no next control. */
  onNext?: () => void
  /** Called on the way back. Absent means this step has no back control. */
  onBack?: () => void
  /** The forward control's text. */
  nextLabel?: string
  /** The back control's text. */
  backLabel?: string
}

/** From the contract's table of state words, so five components share one. */
const STATE_WORD = {
  active: 'current',
  complete: 'complete',
  locked: 'locked',
} as const

export function TutorialStep({
  step,
  max,
  title,
  active = false,
  complete = false,
  locked = false,
  onNext,
  onBack,
  nextLabel = 'Next',
  backLabel = 'Back',
  className,
  children,
  ...rest
}: TutorialStepProps) {
  // The name carries the state, because a screen reader user gets no stroke,
  // no fill and no tick. Order matters: what it is, where it is, then what is
  // true about it.
  const words = [title, `step ${step} of ${max}`]
  if (active) words.push(STATE_WORD.active)
  if (complete) words.push(STATE_WORD.complete)
  if (locked) words.push(STATE_WORD.locked)

  return (
    <div
      {...rest}
      className={['gs-tutorial-step', className].filter(Boolean).join(' ')}
      data-gs-component="tutorial-step"
      data-gs-step={step}
      data-gs-max={max}
      data-gs-active={active ? 'true' : undefined}
      data-gs-complete={complete ? 'true' : undefined}
      data-gs-locked={locked ? 'true' : undefined}
      role="group"
      aria-label={words.join(', ')}
    >
      {/* aria-hidden: the group's label above is the accessible name, and
          announcing the counter again would read the position twice. */}
      <span className="gs-tutorial-step__step" data-gs-scope="tutorial-step" data-gs-part="step" aria-hidden="true">
        Step {step} of {max}
      </span>
      {/* A completed step says so without colour. Emphasis, so it survives
          reduced motion: it is the tick, not a fade. */}
      {complete ? (
        <span
          className="gs-tutorial-step__glyph"
          data-gs-scope="tutorial-step" data-gs-part="glyph"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          <TickGlyph />
        </span>
      ) : null}
      {/* gs-display-type for the shadow the theme puts under the display face;
          the stylesheet sizes it back down to the title. */}
      <span className="gs-tutorial-step__title gs-display-type" data-gs-scope="tutorial-step" data-gs-part="label" aria-hidden="true">
        {title}
      </span>
      <span className="gs-tutorial-step__body" data-gs-scope="tutorial-step" data-gs-part="body">
        {children}
      </span>
      {onBack || onNext ? (
        <span className="gs-tutorial-step__actions" data-gs-scope="tutorial-step" data-gs-part="actions">
          {onBack ? (
            <Button variant="secondary" onClick={onBack}>
              {backLabel}
            </Button>
          ) : null}
          {onNext ? (
            <Button variant="primary" locked={locked} onClick={onNext}>
              {nextLabel}
            </Button>
          ) : null}
        </span>
      ) : null}
    </div>
  )
}

/* Tutorial step. Every value comes from a token; nothing here is a literal colour.

   Specimen 3g draws the step's parts in two places and design/twins/3g.json
   measures ours against both: the title and the body inside the onboarding
   card, and the way forward and the way back as the "Retry / Continue" row at
   the foot of the sheet. The card around them is this component's own. */

.gs-tutorial-step {
  display: grid;
  /* One column, the counter over the title, as the onboarding card in 3g
     stacks them. A counter column beside everything left a third of the card
     empty under "STEP 2 OF 3". The tick, when the step is done, keeps the
     counter's row at the far end. */
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: var(--gs-space-2) var(--gs-space-3);

  padding: var(--gs-space-4);

  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);

  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
  box-shadow: var(--gs-depth-raised);
}

/* The counter is the one step counter the drawing draws, on the coach mark:
   the display face, heavy and in capitals, so "STEP 2 OF 4" reads as a mark
   rather than a sentence. type.figure is the display token nearest it; the
   drawing sets 11px and the label floor is 12. */
.gs-tutorial-step__step {
  grid-column: 1;
  grid-row: 1;
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  text-transform: uppercase;
  white-space: nowrap;
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  color: var(--gs-color-ink-secondary);
}

/* The heading. The drawing sets it in capitals with the display shadow under
   it, the same shadow every number a player reads carries, which is why the
   span carries gs-display-type and this rule only sizes it back to the title.
   Case is read from a title case token that does not exist yet: the drawing
   uppercases four of its eighteen 20px titles and every heading on the 4e
   state cards, which is a theme's decision and not this component's, so the
   value stays `none` until a token says otherwise. */
.gs-tutorial-step__title {
  grid-column: 1 / -1;
  grid-row: 2;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  text-transform: var(--gs-type-title-text-transform, none);
}

/* The line of explanation, in the secondary ink so the title above it is the
   thing read first. */
.gs-tutorial-step__body {
  grid-column: 1 / -1;
  grid-row: 3;
  color: var(--gs-color-ink-secondary);
}

/* The way back and the way forward share the row, as the drawing draws them:
   10px apart and each taking half. */
.gs-tutorial-step__actions {
  grid-column: 1 / -1;
  grid-row: 4;
  display: flex;
  gap: var(--gs-space-gap);
  margin-top: var(--gs-space-2);
}

.gs-tutorial-step__actions > * {
  flex: 1 1 0;
}

.gs-tutorial-step__glyph {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  color: var(--gs-color-positive-solid);
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* The step the sequence is on. A stroke rather than a fill, so it does not read
   as a selection the player made. */
.gs-tutorial-step[data-gs-active='true'] {
  border-color: var(--gs-color-selected);
  border-width: var(--gs-stroke-selected);
}

/* Done. Changes the stroke, adds the tick above and quiets the counter, so it
   is never the colour alone that says so. */
.gs-tutorial-step[data-gs-complete='true'] {
  border-color: var(--gs-color-positive-solid);
  box-shadow: var(--gs-depth-flat);
}

.gs-tutorial-step[data-gs-complete='true'] .gs-tutorial-step__step {
  color: var(--gs-color-positive-solid);
}

/* Locked keeps its shape: available later, not now. Only disabled goes flat,
   and a step is never disabled, because a sequence that cannot be reached at
   all is a sequence the host does not render. */
.gs-tutorial-step[data-gs-locked='true'] {
  border-style: dashed;
  border-color: var(--gs-color-edge);
}
